@mcp.tool()
def create_issue(repo: str, title: str) -> str:
    """Create a GitHub issue."""

schema = {"type": "object", "properties": {"repo": {"type": "string"}, "title": {"type": "string"}, "body": {"type": "string"}, "labels": {"type": "array"}}, "required": ["repo", "title"]}
args = {'repo': 'x', 'title': 'x', 'labels': 'x', 'body': 'x'}
missing = [k for k in schema["required"] if k not in args]
print(missing)

ann = {"destructiveHint": True, "readOnlyHint": True, "openWorldHint": False}
read_only = ann.get("readOnlyHint", False)
destructive = ann.get("destructiveHint", True)
if read_only:
    print("auto-approve")
elif destructive:
    print("ask user (destructive)")
else:
    print("ask user (non-destructive)")

result = {"content": [{"type": "image", "data": "AAAA", "mimeType": "image/x"}, {"type": "text", "text": "part 1"}, {"type": "text", "text": "part 2"}], "isError": False}
texts = [c for c in result["content"] if c["type"] == "text"]
print(len(result["content"]), len(texts), result.get("isError", False))

